mapper.select:
select *
from sync_import_operation
where user_id = #{userId}
  and operation_id = #{operationId}
limit 1

select server_aggregate_id
from sync_import_operation
where user_id = #{userId}
  and local_profile_id = #{localProfileId}
  and aggregate_type = #{aggregateType}
  and aggregate_id = #{aggregateId}
  and status = 'accepted'
  and server_aggregate_id is not null
  and server_aggregate_id != ''
order by id desc
limit 1
